fn numpy_matrix_transpose(x: Vec<Vec<f32>>) -> Vec<Vec<f32>> {
    // Check if input is empty (though problem says non-empty)
    if x.is_empty() {
        return Vec::new();
    }
    
    let rows = x.len();
    let cols = x[0].len();
    
    // Verify all rows have the same length
    for row in &x {
        if row.len() != cols {
            // Return empty matrix or handle error - 
            // but problem says matrix is rectangular, so this shouldn't happen
            return Vec::new();
        }
    }
    
    // Create result matrix with swapped dimensions
    let mut result = vec![vec![0.0; rows]; cols];
    
    // Fill the transposed matrix
    for i in 0..rows {
        for j in 0..cols {
            result[j][i] = x[i][j];
        }
    }
    
    result
}